[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$JobRoot)
$ErrorActionPreference='Stop';$source=Join-Path $JobRoot 'rtx_gpuva_bridge_probe.cpp';$cuda=$env:CUDA_PATH;if(-not$cuda){$cuda='C:\Program Files\NVIDIA GPU Computing Toolkit\CUDA\v13.3'};$vswhere=Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio\Installer\vswhere.exe';$install=&$vswhere -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath;$vcvars=Join-Path $install 'VC\Auxiliary\Build\vcvars64.bat';$object=Join-Path $JobRoot 'probe.obj';$binary=Join-Path $JobRoot 'probe.exe';$log=Join-Path $JobRoot 'compile.log';$command='"{0}" >nul && cl.exe /nologo /std:c++20 /EHsc /MD /W4 /WX /permissive- /I"{1}" /Fo"{2}" /c "{3}" >"{4}" 2>&1 && link.exe /nologo /OUT:"{5}" "{2}" "{6}" d3d12.lib dxgi.lib >>"{4}" 2>&1' -f $vcvars,(Join-Path $cuda 'include'),$object,$source,$log,$binary,(Join-Path $cuda 'lib\x64\cuda.lib');&$env:ComSpec /d /s /c $command;if($LASTEXITCODE-ne 0){throw "compile failed $log"};&$binary|Tee-Object -FilePath (Join-Path $JobRoot 'run.log');if($LASTEXITCODE-ne 0){throw 'probe failed'};Get-FileHash $source,$binary -Algorithm SHA256|ConvertTo-Json|Set-Content -Encoding utf8 (Join-Path $JobRoot 'hashes.json')
